def parse_row(line: str) -> list[str]:
    result: list[str] = []
    current = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        char = line[i]
        if in_quotes:
            if char == '"':
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                    continue
                else:
                    in_quotes = False
            else:
                current.append(char)
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                result.append(''.join(current))
                current = []
            else:
                current.append(char)
        i += 1

    if current:
        result.append(''.join(current))

    return result

