def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen = set()
    result = []
    for row in rows:
        if key in row:
            if row[key] not in seen:
                seen.add(row[key])
                result.append(row)
        else:
            result.append(row)
    return result
